var siteTypeFallbackIcon template.HTML = `<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" class="remixicon" viewBox="0 0 24 24" fill="currentColor"><path d="M13.3414 4C13.1203 4.62556 13 5.29873 13 6H5V20H19V12C19.7013 12 20.3744 11.8797 21 11.6586V21C21 21.5523 20.5523 22 20 22H4C3.44772 22 3 21.5523 3 21V5C3 4.44772 3.44772 4 4 4H13.3414ZM19 8C20.1046 8 21 7.10457 21 6C21 4.89543 20.1046 4 19 4C17.8954 4 17 4.89543 17 6C17 7.10457 17.8954 8 19 8ZM19 10C16.7909 10 15 8.20914 15 6C15 3.79086 16.7909 2 19 2C21.2091 2 23 3.79086 23 6C23 8.20914 21.2091 10 19 10Z"/></svg>`

func findSiteType(t string) (siteTypeIcon, bool) {
	t = strings.ToLower(t)
	for _, s := range siteTypeIcons {
		if t == s.key || (s.contains && strings.Contains(t, s.key)) {
			return s, true
		}
	}
	return siteTypeIcon{}, false
}

// SiteTypeIcon returns the logo for a sites.type value, a generic app icon for unknown types
func SiteTypeIcon(t string) template.HTML {
	if s, ok := findSiteType(t); ok {
		return s.svg
	}
	return siteTypeFallbackIcon
}

// SiteTypeLabel is the display name for a sites.type value
func SiteTypeLabel(t string) string {
	if s, ok := findSiteType(t); ok {
		return s.label
	}
	if t == "" {
		return "Unknown"
	}
	return strings.ToUpper(t[:1]) + strings.ToLower(t[1:])
}

// siteTypeKey is the sprite id suffix for a sites.type value
func siteTypeKey(t string) string {
	if s, ok := findSiteType(t); ok {
		return s.key
	}
	return "app"
}

// svgSymbol turns a standalone svg into a <symbol> plus the small svg that uses it, presentation attributes stay on the using svg so the icon keeps its fill/stroke
func svgSymbol(svg template.HTML, id string) (symbol, use string) {
	raw := string(svg)
	open := svgOpenTagRE.FindStringSubmatch(raw)
	if open == nil {
		return "", raw
	}
	inner := strings.TrimSuffix(raw[len(open[0]):], "</svg>")
	symbol = fmt.Sprintf(`<symbol id="%s" viewBox="%s">%s</symbol>`, id, svgAttr(open[1], "viewBox"), inner)
	attrs := ""
	for _, a := range []string{"width", "height", "fill", "stroke", "stroke-width", "stroke-linecap", "stroke-linejoin"} {
		if v := svgAttr(open[1], a); v != "" {
			attrs += fmt.Sprintf(` %s="%s"`, a, v)
		}
	}
	return symbol, fmt.Sprintf(`<svg%s aria-hidden="true"><use href="#%s"></use></svg>`, attrs, id)
}

// SiteTypeSprite defines the logos of the given types once, rows then use SiteTypeUse
func SiteTypeSprite(types []string) template.HTML {
	var b strings.Builder
	b.WriteString(`<svg xmlns="http://www.w3.org/2000/svg" aria-hidden="true" style="position:absolute;width:0;height:0;overflow:hidden">`)
	seen := map[string]bool{}
	for _, t := range types {
		key := siteTypeKey(t)
		if seen[key] {
			continue
		}
		seen[key] = true
		symbol, _ := svgSymbol(SiteTypeIcon(t), "site-type-"+key)
		b.WriteString(symbol)
	}
	b.WriteString(`</svg>`)
	return template.HTML(b.String())
}

// SiteTypeUse is the logo for a type, pointing at SiteTypeSprite
func SiteTypeUse(t string) template.HTML {
	key := siteTypeKey(t)
	_, use := svgSymbol(SiteTypeIcon(t), "site-type-"+key)
	return template.HTML(use)
}
